/**
 * Error returned by every fallible Apple binding call. Swift sees an `enum
 * CoreError: Error` with these cases. `Cancelled` covers both a call stopped
 * through its `CoreCancellation` (Swift task cancelled) and a core refusal such
 * as a stale credential revision passed to `acknowledge_credentials`; the Swift
 * glue maps the former to `CancellationError` when `Task.isCancelled`.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Malformed caller input; `message` is the core's fixed English reason.
     */
    case Invalid(
        /**
         * Fixed, non-secret reason from the core.
         */message: String
    )
    /**
     * Authenticated decryption, key derivation or OPAQUE verification failed.
     */
    case Crypto
    /**
     * Sign-in failed or no session is loaded.
     */
    case Authentication
    /**
     * The account needs a two-factor code.
     */
    case TwoFactorRequired
    /**
     * The anonymous allowance is used up.
     */
    case SignupRequired
    /**
     * A capability is unavailable; `code`/`reason` are stable identifiers.
     */
    case Unavailable(
        /**
         * Stable machine code.
         */code: String, 
        /**
         * Stable machine reason.
         */reason: String
    )
    /**
     * A local store or resource is locked.
     */
    case Locked
    /**
     * No network connection to the server.
     */
    case Offline
    /**
     * The operation is not allowed for this account, team or session kind.
     */
    case Forbidden
    /**
     * The session expired.
     */
    case Expired
    /**
     * The core aborted the operation (also: stale credential revision).
     */
    case Cancelled
    /**
     * A local I/O operation failed.
     */
    case Io
    /**
     * The server or a stored payload had an invalid or unsupported shape.
     * Swift name `ProtocolError` (uniffi.toml rename: `Protocol` is reserved).
     */
    case ProtocolError
    /**
     * The object changed; read its latest state before retrying.
     */
    case Conflict
    /**
     * Binding failure (runtime task panicked or the core was shut down).
     */
    case Internal(
        /**
         * Fixed, non-secret reason.
         */reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto
        case 3: return .Authentication
        case 4: return .TwoFactorRequired
        case 5: return .SignupRequired
        case 6: return .Unavailable(
            code: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Locked
        case 8: return .Offline
        case 9: return .Forbidden
        case 10: return .Expired
        case 11: return .Cancelled
        case 12: return .Io
        case 13: return .ProtocolError
        case 14: return .Conflict
        case 15: return .Internal(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Invalid(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case .Crypto:
            writeInt(&buf, Int32(2))
        
        
        case .Authentication:
            writeInt(&buf, Int32(3))
        
        
        case .TwoFactorRequired:
            writeInt(&buf, Int32(4))
        
        
        case .SignupRequired:
            writeInt(&buf, Int32(5))
        
        
        case let .Unavailable(code,reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Locked:
            writeInt(&buf, Int32(7))
        
        
        case .Offline:
            writeInt(&buf, Int32(8))
        
        
        case .Forbidden:
            writeInt(&buf, Int32(9))
        
        
        case .Expired:
            writeInt(&buf, Int32(10))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(11))
        
        
        case .Io:
            writeInt(&buf, Int32(12))
        
        
        case .ProtocolError:
            writeInt(&buf, Int32(13))
        
        
        case .Conflict:
            writeInt(&buf, Int32(14))
        
        
        case let .Internal(reason):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


